import{_ as e,o,c as p,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-076","description":"","frontmatter":{"date":"2020-10-19T20:36:58","title":"写作课作业-076","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[],"relativePath":"posts/homework/076.md","filePath":"posts/homework/076.md"}'),s={name:"posts/homework/076.md"};function r(_,t,l,i,c,n){return o(),p("div",null,[...t[0]||(t[0]=[a("<blockquote><p>10.3写作作业：《微信互联网平民创业》之《8.问问自己真的适合卖课吗？》</p></blockquote><blockquote><p>在微信互联网这个生态之中，现在能卖的东⻄可以分为两种:</p><ul><li>实物商品</li><li>虚拟商品</li></ul><p>那么，虚拟商品除了服务之外，最常⻅的就是各种「课程」。</p><p>更看重⻓期价值的好商人，不喜欢赚「靠信息不对称才能赚到的钱」。</p><p>难道说我们就不能卖课了嘛?答案是，能!当然能!—— 只不过，要卖真正有价值的课。</p></blockquote><p>其实读这个章节的时候，自己是比较矛盾的，除了卖课我还能选什么呢？卖课自己好像也没有卖出去呀，比如写作课。</p><p>首先得到和极客时间，用最简单的方式理解是在卖课，而且卖得很成功的。然后我也看到，就算是罗永浩这样的大V，在卖货的时候对商品也是精挑细选的。</p><p>于是我是这样理解的，我通过学习极客时间的课程，实际使用和写读书笔记，推广相关的课程这样的卖课思路应该是可以的，我也通过写读书笔记成交过一两单。但对应到上个章节《为什么总是要更重视选择？》，我写极客时间的读书笔记是不是思考的惯性呢？</p><p>之前也订阅了GitChat，使用的是微课和微信群的方式，但是最终发现GitChat上对作者，做课程的质量控制不够，慢慢的上面的课也就没怎么看，后面也就没有订阅了。</p>",6)])])}const u=e(s,[["render",r]]);export{m as __pageData,u as default};
